  <script>
    const form = document.getElementById('leadForm');
    const submitButton = document.getElementById('submitButton');
    const buttonText = document.getElementById('buttonText');
    const spinner = document.getElementById('spinner');
    const statusMessage = document.getElementById('statusMessage');

    const webhookUrl =
      'https://afaqkhan67.app.n8n.cloud/webhook/ai-sales-agent';

    function setLoading(isLoading) {
      submitButton.disabled = isLoading;
      spinner.style.display = isLoading ? 'inline-block' : 'none';
      buttonText.textContent = isLoading
        ? 'AI is analyzing your lead...'
        : 'Analyze My Business';
    }

    function showStatus(type, message) {
      statusMessage.className = 'status ' + type;
      statusMessage.textContent = message;
    }

    form.addEventListener('submit', async function(event) {
      event.preventDefault();

      setLoading(true);
      statusMessage.className = 'status';
      statusMessage.textContent = '';

      const formData = new FormData(form);

      const payload = {
        full_name: String(formData.get('full_name') || '').trim(),
        email: String(formData.get('email') || '').trim(),
        phone: String(formData.get('phone') || '').trim(),
        company: String(formData.get('company') || '').trim(),
        industry: String(formData.get('industry') || '').trim(),
        service_required: String(
          formData.get('service_required') || ''
        ).trim(),
        business_size: String(
          formData.get('business_size') || ''
        ).trim(),
        monthly_leads: String(
          formData.get('monthly_leads') || ''
        ).trim(),
        budget: String(formData.get('budget') || '').trim(),
        pain_point: String(formData.get('pain_point') || '').trim()
      };

      try {
        const response = await fetch(webhookUrl, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json'
          },
          body: JSON.stringify(payload)
        });

        if (!response.ok) {
          throw new Error('The automation returned HTTP ' + response.status);
        }

        showStatus(
          'success',
          'Success! Your information has been received and analyzed. Our sales team will review the recommended next action.'
        );

        form.reset();
      } catch (error) {
        console.error(error);

        showStatus(
          'error',
          'We could not submit your information. Please check that the n8n workflow is published and try again.'
        );
      } finally {
        setLoading(false);
      }
    });
  </script>
